export const GLOSSARY_SHARD = Object.freeze({"bitcoin":{"slug":"bitcoin","cat":"basics","en":"Bitcoin (BTC)","contentLocale":"ja","term":"ビットコイン（BTC）","aka":["BTC","Bitcoin"],"short":"ビットコイン（BTC）とは、2009年に運用が始まった最初の暗号資産で、発行上限2100万枚、管理者のいないネットワークでプルーフ・オブ・ワークにより運営されています。","body":[["ビットコインは、",["サトシ","satoshi"],"・ナカモトと名乗る人物またはグループが2008年に論文を公開し、2009年にネットワークが稼働しました。中央銀行や企業が発行を管理するのではなく、マイナー（採掘者）が計算競争を通じてブロックを追加し、その報酬として新しいBTCが発行されます。"],["発行上限は2100万枚と決まっており、約4年ごとに訪れる",["半減期","bitcoin-halving"],"でブロック報酬が半分になります。2024年4月の半減期で報酬は3.125 BTCになりました。この希少性から「デジタルゴールド」と呼ばれることがあります。"],["1 BTCは1億サトシに分割でき、少額でも購入できます。2024年1月には米国で現物",["ビットコインETF","spot-bitcoin-etf"],"の取引が始まり、証券口座を通じて間接的に投資する手段も広がりました。ただし価格変動は大きく、短期間で数十%動くこともあります。"]],"example":"例えば、1 BTC = 900万円のときに3万円分を購入すると、受け取る量は約0.00333 BTC、サトシに換算すると約33万3,333サトシです。1 BTCが1,000万円に上がれば評価額は約3万3,333円、800万円に下がれば約2万6,667円になります。","mistakes":["1 BTC丸ごとでないと買えないと思い込み、少額購入の選択肢を知らないこと。","出金先アドレスのネットワークを確認せず、対応していないチェーンのアドレスにBTCを送ってしまうこと。","「発行上限があるから価格は必ず上がる」と考え、価格変動のリスクを無視すること。"],"faq":[{"q":"ビットコインは誰が管理していますか？","a":"特定の管理者はいません。世界中のノードとマイナーが共通のルールに従ってネットワークを運営し、ルールの変更には参加者の広い合意が必要です。"},{"q":"ビットコインはいくらから買えますか？","a":"1億分の1 BTCまで分割できるため、取引所の最小注文額以上であれば少額から購入できます。最小額は取引所ごとに異なります。"},{"q":"ビットコインが発行上限に達したらどうなりますか？","a":"新規発行がなくなり、マイナーの収入は取引手数料が中心になると考えられています。上限への到達は2140年頃と見積もられています。"}],"title":"ビットコイン（BTC）とは？仕組みと特徴をやさしく解説","description":"ビットコインの仕組み、発行上限2100万枚、半減期、少額から買える理由を初心者向けにわかりやすく解説します。","related":[["satoshi","サトシ（sats）","サトシ（sats）とは、ビットコインの最小単位で、1サトシは1億分の1 BTC（0.00000001 BTC）に相当します。"],["bitcoin-halving","ビットコイン半減期","ビットコイン半減期とは、21万ブロックごと（約4年ごと）に、マイナーが受け取る新規発行のブロック報酬が半分になるイベントのことです。"],["proof-of-work","プルーフ・オブ・ワーク（PoW）","プルーフ・オブ・ワーク（PoW）とは、マイナーが大量の計算で競争し、最初に条件を満たす答えを見つけた者が新しいブロックを追加できるコンセンサスの仕組みです。"],["mining","マイニング（採掘）","マイニング（採掘）とは、プルーフ・オブ・ワークのブロックチェーンで計算処理を行って取引をブロックにまとめ、その報酬として新規発行の暗号資産と手数料を受け取る活動です。"],["spot-bitcoin-etf","ビットコイン現物ETF","ビットコイン現物ETFとは、運用会社が実際のビットコインを保有し、その価格に連動するよう設計された、証券取引所に上場している投資信託のことです。"]],"lesson":{"id":"E01","slug":"can-i-buy-part-of-a-bitcoin","ep":1,"title":"ビットコイン一枚は高すぎる。それでも少しだけ買えますか？"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":true},"proof-of-work":{"slug":"proof-of-work","cat":"basics","en":"Proof of work (PoW)","contentLocale":"ja","term":"プルーフ・オブ・ワーク（PoW）","aka":["PoW","Proof of Work","作業証明"],"short":"プルーフ・オブ・ワーク（PoW）とは、マイナーが大量の計算で競争し、最初に条件を満たす答えを見つけた者が新しいブロックを追加できるコンセンサスの仕組みです。","body":[["マイナーは、ブロックのデータに含める数値（ナンス）を変えながらハッシュ計算を繰り返し、ネットワークが定める難易度を下回るハッシュ値を探します。答えを見つけるのは難しい一方、正しいかどうかの確認は簡単なので、他の",["ノード","node"],"はすぐに検証できます。"],["この仕組みでは、ブロックを書き換えるには膨大な計算をやり直す必要があり、ネットワーク全体の計算力（",["ハッシュレート","hash-rate"],"）の過半数を握らない限り、改ざんは極めて困難です。",["ビットコイン","bitcoin"],"はPoWの代表例で、ライトコインやドージコインもPoWを採用しています。"],["難易度は自動で調整されるため、マイナーが増えてもブロック生成の間隔はほぼ一定に保たれます。欠点としてよく挙げられるのは電力消費の大きさで、",["イーサリアム","ethereum"],"は2022年9月にPoWから",["プルーフ・オブ・ステーク（PoS）","proof-of-stake"],"へ移行しました。"]],"example":["例えば、ネットワーク全体のハッシュレートが600 EH/sで、ある",["マイニング","mining"],"事業者が6 EH/sを持っているとします。シェアは1%なので、1日約144ブロックのうち平均1.44ブロック程度を見つけられる計算です。ブロック報酬が3.125 BTCなら、1日の報酬の期待値は約4.5 BTC（取引手数料を除く）になります。"],"mistakes":["PoWの「ワーク（仕事）」を、人が取引の中身を確認する作業だと誤解すること。","ハッシュレートが上がれば価格も必ず上がると単純に結びつけること。","自宅のパソコンで今もビットコインを効率よく採掘できると考えること。"],"faq":[{"q":"PoWとPoSの違いは何ですか？","a":"PoWは計算力の競争でブロックの作成者を決め、PoSはステークした暗号資産の量などに応じて検証者を選びます。PoSは一般に電力消費がはるかに少ないとされます。"},{"q":"PoWの51%攻撃とは何ですか？","a":"ネットワーク全体のハッシュレートの過半数を握った攻撃者が、取引の順序を書き換えたり二重支払いを試みたりする攻撃です。大規模なチェーンでは莫大なコストがかかるため、現実的には困難です。"}],"title":"プルーフ・オブ・ワーク（PoW）とは？仕組みを解説","description":"プルーフ・オブ・ワーク（PoW）の仕組み、マイニングや難易度調整との関係、PoSとの違いを初心者向けに解説します。","related":[["mining","マイニング（採掘）","マイニング（採掘）とは、プルーフ・オブ・ワークのブロックチェーンで計算処理を行って取引をブロックにまとめ、その報酬として新規発行の暗号資産と手数料を受け取る活動です。"],["hash-rate","ハッシュレート","ハッシュレートとは、プルーフ・オブ・ワーク（PoW）のブロックチェーンでマイニング機器が1秒間に計算できるハッシュの回数のことで、ネットワーク全体の計算力を表します。"],["proof-of-stake","プルーフ・オブ・ステーク（PoS）","プルーフ・オブ・ステーク（PoS）とは、暗号資産を担保として預け入れ（ステーク）したバリデーターが、ブロックの提案と検証を担うコンセンサスの仕組みです。"],["blockchain","ブロックチェーン","ブロックチェーンとは、取引記録を「ブロック」にまとめて時系列に鎖のようにつなぎ、多数のコンピューターで共有・検証する分散型の台帳技術です。"],["bitcoin-halving","ビットコイン半減期","ビットコイン半減期とは、21万ブロックごと（約4年ごと）に、マイナーが受け取る新規発行のブロック報酬が半分になるイベントのことです。"]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"token-unlock":{"slug":"token-unlock","cat":"basics","en":"Token unlock","contentLocale":"ja","term":"トークンアンロック","aka":["アンロック","ロック解除","Token unlock"],"short":"トークンアンロックとは、チームや投資家などに配分されロックされていたトークンが、決められたスケジュールに従って売却や移転できるようになることです。","body":["新しいプロジェクトでは、関係者がすぐに売れないよう、トークンを一定期間ロックするのが一般的です。最初に一定期間まったく解除されない「クリフ」を設け、その後に毎月や四半期ごとに少しずつ解除する「ベスティング」が多く使われます。",["アンロックは",["流通量","circulating-supply"],"を増やすため、需要が変わらなければ売り圧力になりやすいイベントです。特に、流通量に比べて大きな割合のトークンが一度に解除される場合や、初期投資家の取得価格が現在価格より大幅に低い場合は注目が集まります。"],["ただし、アンロックされたトークンがすべて売られるわけではありません。",["ステーキング","staking"],"に回されたり、長期保有されたりすることもあります。アンロックの予定は公式資料や専用のトラッキングサイトで確認でき、日付と量を事前に把握しておくことが大切です。"]],"example":"例えば、流通量が1億枚のトークンで、来週2,500万枚のアンロックが予定されているとします。流通量は25%増えます。価格が2ドルなら解除分は5,000万ドル相当で、1日の取引高が1,000万ドルしかない銘柄なら、その一部が売られるだけでも価格に大きな影響が出る可能性があります。","mistakes":["アンロックの予定を確認せずに、上場直後の低流通トークンを買うこと。","アンロック量を総供給量とだけ比べ、現在の流通量や取引高に対する大きさを見落とすこと。","アンロックがあれば必ず価格が下がると決めつけること。"],"faq":[{"q":"アンロックの日程はどこで確認できますか？","a":"プロジェクトのトークノミクス資料やホワイトペーパーのほか、トークンアンロック情報をまとめたデータサイトで確認できます。"},{"q":"クリフとベスティングの違いは何ですか？","a":"クリフは最初に解除が一切ない期間で、ベスティングはその後に段階的に解除されていく仕組みです。"}],"title":"トークンアンロックとは？価格への影響と確認方法","description":"トークンアンロックの意味、クリフとベスティングの違い、流通量や価格への影響と事前に確認する方法を解説します。","related":[["tokenomics","トークノミクス","トークノミクスとは、暗号資産トークンの供給量、配分、発行スケジュール、用途、焼却などをまとめた経済設計の全体像のことです。"],["circulating-supply","流通供給量","流通供給量とは、現在市場で自由に取引できる状態にある暗号資産の枚数のことで、ロック中のトークンやまだ発行されていない分は含まれません。"],["fully-diluted-valuation","完全希薄化後時価総額（FDV）","完全希薄化後時価総額（FDV）とは、トークンの現在価格に最大供給量（または総供給量）を掛けた値で、将来すべてのトークンが流通した場合の評価額を示します。"],["airdrop","エアドロップ","エアドロップとは、プロジェクトが特定の条件を満たしたウォレットやユーザーに、トークンを無料で配布することです。"]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"limit-order":{"slug":"limit-order","cat":"trading","en":"Limit order","contentLocale":"ja","term":"指値注文","aka":["指値","リミット注文","Limit order"],"short":"指値注文とは、売買したい価格を自分で指定し、その価格かそれより有利な価格になったときにだけ約定させる注文方法です。","body":["買いの指値は指定価格以下、売りの指値は指定価格以上でのみ約定します。今の価格より安く買いたい、高く売りたいときに使い、条件を満たすまで注文は板に並んで待ちます。",["約定価格が想定とずれにくいことが最大の利点です。板に並ぶ注文は",["流動性","liquidity"],"を提供する側（メイカー）となるため、多くの取引所ではテイカーより低い",["メイカー手数料","maker-taker-fees"],"が適用されます。ただし、現在の売り気配より高い買い指値を出すとすぐに約定し、テイカー扱いになる点に注意しましょう。"],["欠点は、価格が指定値まで来なければ約定しないことです。相場が反対方向に走れば、チャンスを逃すこともあります。また、一部だけが約定する「部分約定」も起こり得ます。注文の有効期限（GTCなどの",["執行条件","time-in-force"],"）も確認しておきましょう。"]],"example":"例えば、ETHが3,200ドルのときに、3,100ドルで1 ETHを買う指値注文を出したとします。価格が3,080ドルまで下がれば、3,100ドル以下で約定します。メイカー手数料が0.02%なら、手数料は0.62ドルです。一方、価格が3,120ドルまでしか下がらずに反発し、3,400ドルまで上がった場合、注文は約定せず、その上昇には参加できません。","mistakes":["現在の売り気配より高い買い指値を出し、意図せずすぐに約定してしまうこと。","約定しなかった古い指値注文を取り消し忘れ、後で予想外に約定すること。","買いと売りを取り違えて指値を出し、思わぬ価格で売買してしまうこと。"],"faq":[{"q":"指値注文は必ず指定した価格で約定しますか？","a":"指定価格か、それより有利な価格で約定します。ただし価格が指定値に届いても、先に並んでいる注文の量によっては約定しないこともあります。"},{"q":"指値注文の手数料は安いですか？","a":"板に並んでから約定した場合、多くの取引所でメイカー手数料が適用され、テイカー手数料より低いのが一般的です。手数料体系は取引所ごとに異なります。"}],"title":"指値注文とは？仕組みと成行注文との違い","description":"指値注文の仕組みとメリット、約定しないリスク、メイカー手数料との関係、成行注文との違いを具体例で解説します。","related":[["market-order","成行注文","成行注文とは、価格を指定せずに、その時点で板にある最も有利な価格から順に、すぐに売買を成立させる注文方法です。"],["post-only-order","ポストオンリー注文","ポストオンリー注文とは、板に並ぶメイカー注文としてのみ受け付けられ、すぐに約定してテイカーになる場合は自動で取り消される指値注文の設定です。"],["time-in-force","執行条件（GTC・IOC・FOK）","執行条件（タイムインフォース）とは、注文をいつまで有効にし、約定しなかった分をどう扱うかを決める設定で、代表的なものにGTC・IOC・FOKがあります。"],["order-book","板（オーダーブック）","板（オーダーブック）とは、取引所に出されている買い注文と売り注文を価格ごとに並べた一覧で、どの価格にどれだけの注文が待っているかを示します。"],["maker-taker-fees","メイカー手数料・テイカー手数料（Maker/Taker）","メイカー手数料・テイカー手数料とは、板に注文を置いて流動性を提供した側（メイカー）と、板の注文を即座に約定させた側（テイカー）で分けて設定される取引手数料のことです。"]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"成行、指値、キャンセル：それぞれ何を解決するのか？"},"coin":null,"tool":null,"cta":true},"insurance-fund":{"slug":"insurance-fund","cat":"derivatives","en":"Insurance fund","contentLocale":"ja","term":"保険基金（インシュアランスファンド）","aka":["インシュアランスファンド","保険ファンド","insurance fund"],"short":"保険基金とは、先物取引所が強制ロスカットで証拠金を超える損失が出たときの穴埋めに使うために積み立てている資金で、自動デレバレッジの発動を防ぐ役割を持ちます。","body":[[["強制ロスカット","liquidation"],"は、ポジションの証拠金がゼロになる価格（破産価格）より手前で行われます。清算注文が破産価格より有利な価格で約定すれば、残った証拠金の一部は保険基金に積み立てられます。逆に急変で破産価格より不利な価格でしか約定できなかった場合は、その不足分が保険基金から支払われます。"],["保険基金があることで、清算されたトレーダーの損失が他の利用者に転嫁されにくくなります。保険基金が十分にあれば、利益を出しているトレーダーのポジションが強制的に縮小される",["自動デレバレッジ（ADL）","auto-deleveraging"],"の発動も抑えられます。"],["多くの大手取引所は保険基金の残高を公開しており、銘柄ごとに分けている場合もあります。急激な相場で保険基金が大きく減ることもあるため、残高の推移は取引所の健全性を見る材料の一つになります。ただし、",["プルーフ・オブ・リザーブ","proof-of-reserves"],"とは別のもので、利用者の",["預かり資産","total-value-locked"],"全体を保証するものではありません。"]],"example":["あるトレーダーのBTC",["ロング","long-and-short"],"の破産価格が57,000 ",["USDT","usdt"],"、清算価格が57,300 USDTだとします。価格が下がって57,300 USDTで清算され、1 BTCの清算注文がそのまま57,300 USDTで約定すれば、破産価格との差300 USDTが保険基金に入ります。一方、急落で板が薄く、56,600 USDTでしか約定できなければ、破産価格との差400 USDTが不足し、保険基金から補われます。"],"mistakes":["保険基金を、取引所が破綻したときに利用者の資産を守る保険だと誤解する。","清算時に残った証拠金がすべて返ってくると思い込み、保険基金に入る仕組みを知らない。","保険基金の残高が多ければADLは絶対に起きないと考える。"],"faq":[{"q":"保険基金の残高はどこで確認できますか？","a":"多くの大手取引所では、保険基金の残高や推移を専用ページで公開しています。銘柄ごとに分けて表示している取引所もあります。"},{"q":"保険基金は取引所の破綻にも備えていますか？","a":"いいえ、保険基金は先物の清算で生じた不足分を埋めるためのものです。預かり資産の保全とは別の仕組みです。"}],"title":"保険基金とは？先物取引所での役割と仕組み","description":"先物取引所の保険基金（インシュアランスファンド）の役割、清算時に積み立てと補填が起きる仕組み、ADLとの関係を解説します。","related":[["auto-deleveraging","自動デレバレッジ（ADL）","自動デレバレッジ（ADL）とは、清算されたポジションの損失を保険基金で補いきれないときに、反対側で利益が出ているトレーダーのポジションを取引所が強制的に縮小する仕組みです。"],["liquidation","強制ロスカット（清算）","強制ロスカット（清算）とは、レバレッジ取引で損失が膨らみ、証拠金が維持証拠金を下回ったときに、取引所がポジションを強制的に決済する仕組みです。"],["proof-of-reserves","準備金証明（プルーフ・オブ・リザーブ）","準備金証明（PoR）とは、取引所が利用者から預かった暗号資産と同額以上の資産を実際に保有していることを、ブロックチェーン上のデータなどで示す仕組みです。"],["mark-price","マーク価格","マーク価格とは、先物の含み損益や強制ロスカットの判定に使われる「公正な評価価格」のことで、複数の現物取引所の価格をもとに計算され、一時的な価格操作の影響を受けにくくしています。"]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"強制決済（清算）：強制終了のボタンを押したのは誰か"},"coin":null,"tool":"/liquidations","cta":false},"block-confirmations":{"slug":"block-confirmations","cat":"wallets-security","en":"Block confirmations","contentLocale":"ja","term":"ブロック承認数（コンファメーション）","aka":["承認数","コンファメーション","confirmations","確認数"],"short":"ブロック承認数とは、取引が含まれたブロックの後にいくつのブロックが積み重なったかを示す数で、多いほど取引が覆される可能性が低くなります。","body":["取引がブロックに取り込まれた時点で1承認となり、その後ブロックが1つ追加されるごとに承認数が1つ増えます。後から取引を書き換えるには、その上に積まれたブロックをすべてやり直す必要があるため、承認数が多いほど安全です。",["取引所は銘柄ごとに、入金を反映するのに必要な承認数を決めています。ブロック生成の間隔はチェーンによって異なり、",["ビットコイン","bitcoin"],"はおよそ10分、",["イーサリアム","ethereum"],"はおよそ12秒です。そのため必要な承認数が同じでも、待ち時間は大きく変わります。"],"必要承認数は取引所や時期によって変わることがあります。正確な数は、利用する取引所の入金画面や手数料・入金ルールのページで確認しましょう。"],"example":"ある取引所がビットコイン入金の反映に2承認、出金可能になるまでに6承認を求めているとします。ブロック間隔を平均10分とすると、反映までの目安は約20分、出金できるまでは約60分です。一方、同じ取引所でイーサリアムの入金に64承認が必要だとしても、12秒かける64で約13分と、ビットコインより早く反映されます。","mistakes":["承認数が足りない段階で、入金が失敗したと思い込んで何度もサポートに連絡すること。","チェーンごとのブロック間隔の違いを考えずに、待ち時間を予想すること。","1承認の段階で、個人間取引の相手に商品を渡してしまうこと。"],"faq":[{"q":"承認数はどこで確認できますか？","a":"取引ハッシュ（TxID）をブロックエクスプローラーで検索すると表示されます。取引所の入金履歴画面にも、現在の承認数と必要承認数が表示されることがあります。"},{"q":"承認がなかなか増えないのはなぜですか？","a":"取引がまだブロックに取り込まれていない可能性があります。ネットワークの混雑時に手数料を低く設定すると、未承認のまま待たされることがあります。"}],"title":"ブロック承認数とは？入金が反映されるまでの目安","description":"ブロック承認数（コンファメーション）の意味、取引所が承認数を求める理由、チェーンごとの入金反映時間の目安を解説します。","related":[["transaction-hash","トランザクションハッシュ（TxID）","トランザクションハッシュ（TxID）とは、ブロックチェーン上の個々の取引に付けられる固有の識別子で、送金の状況を誰でも確認できる「追跡番号」の役割を果たします。"],["block-explorer","ブロックエクスプローラー","ブロックエクスプローラーとは、ブロックチェーン上の取引、アドレスの残高、ブロックの情報を検索して閲覧できるウェブサービスのことです。"],["mempool","メンプール（Mempool）","メンプールとは、送信されたもののまだブロックに取り込まれていない未承認の取引が一時的に待機している場所のことです。"],["blockchain","ブロックチェーン","ブロックチェーンとは、取引記録を「ブロック」にまとめて時系列に鎖のようにつなぎ、多数のコンピューターで共有・検証する分散型の台帳技術です。"]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"「送金完了」と出ているのに届かない。どこを調べるべき？"},"coin":null,"tool":null,"cta":false},"impermanent-loss":{"slug":"impermanent-loss","cat":"defi","en":"Impermanent loss","contentLocale":"ja","term":"インパーマネントロス（変動損失）","aka":["インパーマネントロス","IL","impermanent loss","変動損失"],"short":"インパーマネントロスとは、AMMの流動性プールに資産を預けている間にトークンの価格比が変わることで、単に保有していた場合より資産価値が少なくなる損失のことです。","body":[["AMMの",["プール","liquidity-pool"],"は、価格が動くと値上がりしたトークンを売り、値下がりしたトークンを買う形で自動的に比率を調整します。そのため、片方が大きく値上がりすると、プールにいるあなたの持ち分ではその上昇の恩恵を一部しか受けられません。"],"「インパーマネント（一時的）」と呼ばれるのは、価格比が預けたときの水準に戻れば損失が消えるためです。しかし価格比が変わったまま引き出すと、損失は確定します。",["価格比の変化が大きいほど損失は大きくなります。目安として、片方の価格が2倍になると約5.7%、4倍になると約20%の差が生じます。手数料収入がこの差を上回るかどうかが、",["流動性","liquidity"],"提供の損益を左右します。"]],"example":["ETHが2,000 USDCのときに、1 ETHと2,000 ",["USDC","usdc"],"、合計4,000ドル分をプールに預けたとします。その後ETHが4,000 USDCに上がると、プール内のあなたの持ち分は約0.707 ETHと約2,828 USDCになり、価値は約5,657ドルです。一方、預けずに1 ETHと2,000 USDCを持っていれば6,000ドルでした。差の約343ドル、約5.7%がインパーマネントロスです。手数料収入がこれより少なければ、預けない方が有利だったことになります。"],"mistakes":["資産額が増えていれば損はしていないと考え、単純保有との比較をしないこと。","価格変動の大きいトークンのペアで、手数料収入だけを見て提供を始めること。","価格が戻るのを待つうちに、さらに比率が離れて損失が拡大すること。"],"faq":[{"q":"インパーマネントロスを避ける方法はありますか？","a":"ステーブルコイン同士など、価格が連動しやすいペアを選ぶと小さくなりやすいです。完全に避けることはできないため、手数料収入と比較して判断します。"},{"q":"価格が下がった場合もインパーマネントロスは出ますか？","a":"出ます。上昇でも下落でも、預けたときの価格比から離れるほど損失は大きくなります。価格が半分になった場合も約5.7%の差が生じます。"}],"title":"インパーマネントロスとは？計算例でわかる仕組み","description":"インパーマネントロス（変動損失）の意味、AMMで損失が生じる理由、価格が2倍になったときの計算例と手数料との比べ方を解説します。","related":[["liquidity-pool","流動性プール（リクイディティプール）","流動性プールとは、DEXで取引相手として機能するように、利用者が2種類以上のトークンを預け入れてつくる資金の集まりで、預けた人は取引手数料の一部を受け取ります。"],["amm","AMM（自動マーケットメーカー）","AMM（自動マーケットメーカー）とは、板で売り手と買い手を突き合わせる代わりに、流動性プールと数式で自動的に価格を決めて取引を成立させる仕組みです。"],["yield-farming","イールドファーミング","イールドファーミングとは、DeFiのプロトコルに暗号資産を預けたり流動性を提供したりして、手数料や報酬トークンなどの利回りを得る運用方法です。"],["apr-vs-apy","APRとAPYの違い（年利・年間利回り）","APRは複利を含まない単純な年利、APYは得た利息を再投資する複利効果を含めた年間利回りで、同じ金利でもAPYの方が高い数字になります。"]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"liquid-staking":{"slug":"liquid-staking","cat":"defi","en":"Liquid staking","contentLocale":"ja","term":"リキッドステーキング","aka":["リキッドステーキングトークン","LST","liquid staking","流動性ステーキング"],"short":"リキッドステーキングとは、暗号資産をステーキングすると同時に、その預け入れを表すトークンを受け取り、ロックされた資産を他の用途にも使えるようにする仕組みです。","body":[["代表例は",["イーサリアム","ethereum"],"のLido（stETH）やRocket Pool（rETH）です。ETHを預けると、その証書となるリキッドステーキングトークン（LST）が発行されます。LSTは報酬を反映して価値や数量が増え、DEXで売ったり、DeFiの担保に使ったりできます。"],["通常の",["ステーキング","staking"],"ではロックや解除待ちの間に資産が動かせませんが、LSTを売れば実質的にすぐ現金化できます。これが「リキッド（流動的）」と呼ばれる理由です。"],["リスクとしては、プロトコルの",["スマートコントラクト","smart-contract"],"の脆弱性、運営する",["バリデーター","validator"],"のスラッシング、市場でLSTが元の資産より安く取引される乖離（",["デペッグ","depeg"],"）があります。特に急な売りが集中すると、乖離が広がることがあります。"]],"example":"あなたが10 ETHをリキッドステーキングに預け、10 stETHを受け取ったとします。年率3%相当の報酬が反映されれば、1年後には約10.3 ETH分の価値になります。ところが市場が混乱して、stETHが一時的に1 ETHあたり0.95 ETHで取引されたとします。このとき急いで売れば、10.3 stETHは約9.79 ETHにしかならず、元の10 ETHを下回ります。","mistakes":["LSTが常に元の資産と1対1で売れると思い込むこと。","LSTを担保にした借入でレバレッジをかけ、乖離時に清算されること。","リキッドステーキングのプロトコル名を検索して、偽サイトに資産を預けること。"],"faq":[{"q":"リキッドステーキングと通常のステーキングの違いは何ですか？","a":"通常のステーキングは資産がロックされますが、リキッドステーキングではLSTを受け取るため売却やDeFiでの運用ができます。その分、スマートコントラクトや乖離のリスクが加わります。"},{"q":"LSTはいつでも元の資産に戻せますか？","a":"プロトコルを通じた償還には待機期間があることが一般的です。すぐに戻したい場合は市場で売ることになり、そのときの価格は乖離の影響を受けます。"}],"title":"リキッドステーキングとは？LSTの仕組みとリスク","description":"リキッドステーキングの意味、stETHなどLSTの仕組み、通常のステーキングとの違いと、デペッグなどの特有のリスクを解説します。","related":[["staking","ステーキング","ステーキングとは、プルーフ・オブ・ステーク型のブロックチェーンで暗号資産を預け入れてネットワークの運営に参加し、その対価として報酬を受け取る仕組みです。"],["restaking","リステーキング","リステーキングとは、すでにステーキングしている資産やリキッドステーキングトークンを、別のサービスの安全性確保にも再利用し、追加の報酬を得ようとする仕組みです。"],["wrapped-token","ラップトークン（Wrapped Token）","ラップトークンとは、ある暗号資産を別のブロックチェーンや規格で使えるようにするため、元の資産を裏付けとして1対1で発行されたトークンです。"],["depeg","デペッグ（Depeg）","デペッグとは、1ドルなど特定の価値に連動するよう設計されたステーブルコインやトークンの価格が、その目標値から大きく離れてしまう状態のことです。"]],"lesson":null,"coin":{"slug":"lido-dao","name":"Lido DAO","symbol":"LDO"},"tool":null,"cta":false},"restaking":{"slug":"restaking","cat":"defi","en":"Restaking","contentLocale":"ja","term":"リステーキング","aka":["restaking","再ステーキング","LRT"],"short":"リステーキングとは、すでにステーキングしている資産やリキッドステーキングトークンを、別のサービスの安全性確保にも再利用し、追加の報酬を得ようとする仕組みです。","body":[[["イーサリアム","ethereum"],"ではEigenLayerがこの仕組みを広めました。",["ステーク","staking"],"したETHやLSTをリステーキングすると、そのセキュリティを他のプロトコル（",["オラクル","oracle"],"、",["ブリッジ","cross-chain-bridge"],"、データ可用性サービスなど）にも提供し、その対価として追加報酬を受け取ります。"],"リステーキングの預け入れを表すトークンはLRT（リキッドリステーキングトークン）と呼ばれ、LSTと同じようにDeFiで使えるものもあります。報酬の一部はポイントや新しいトークンの配布という形をとることも多くあります。",["利回りが上乗せされる分、リスクも重なります。元のステーキングのリスクに加え、追加で守るサービスでの不正や障害によるスラッシング、LRTの",["デペッグ","depeg"],"、複数の",["スマートコントラクト","smart-contract"],"への依存が生じます。仕組みはまだ新しく、条件も変わりやすい分野です。"]],"example":"あなたが20 ETHをステーキングして年率3%相当の報酬を得ているとします。これをリステーキングして、追加で年率2%相当の報酬が得られると仮定すると、合計の報酬は1年で約1 ETHになります。一方、追加で守ったサービスでの障害により、ステークの1%がスラッシングされた場合、0.2 ETHを失います。追加報酬0.4 ETHのうち半分が消える計算で、リスクと報酬の釣り合いを考える必要があります。","mistakes":["リステーキングの追加報酬を、元のステーキング報酬と同じくらい安全なものだと考えること。","ポイントやエアドロップ期待だけで、仕組みを理解せずに大きな金額を預けること。","LRTを担保に何重にもレバレッジをかけ、デペッグ時に連鎖的に清算されること。"],"faq":[{"q":"リステーキングとリキッドステーキングの違いは何ですか？","a":"リキッドステーキングはステーキング資産をトークン化して流動性を持たせる仕組みです。リステーキングはそのステーキング資産を別のサービスの安全性確保にも再利用し、追加報酬を狙う仕組みです。"},{"q":"リステーキングはETH以外でもできますか？","a":"他のチェーンでも類似の仕組みが登場していますが、対応資産や条件はプロトコルごとに異なります。利用前に公式ドキュメントで確認しましょう。"}],"title":"リステーキングとは？仕組みと上乗せされるリスク","description":"リステーキングの意味、EigenLayerやLRTの仕組み、追加報酬と引き換えに重なるスラッシングやデペッグのリスクを解説します。","related":[["liquid-staking","リキッドステーキング","リキッドステーキングとは、暗号資産をステーキングすると同時に、その預け入れを表すトークンを受け取り、ロックされた資産を他の用途にも使えるようにする仕組みです。"],["staking","ステーキング","ステーキングとは、プルーフ・オブ・ステーク型のブロックチェーンで暗号資産を預け入れてネットワークの運営に参加し、その対価として報酬を受け取る仕組みです。"],["validator","バリデーター（検証者）","バリデーターとは、プルーフ・オブ・ステークのブロックチェーンで暗号資産をステークし、ブロックの提案や取引の検証を行うネットワーク参加者のことです。"],["smart-contract","スマートコントラクト","スマートコントラクトとは、ブロックチェーン上に置かれ、あらかじめ決められた条件が満たされると自動的に実行されるプログラムのことです。"]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"defi-lending":{"slug":"defi-lending","cat":"defi","en":"DeFi lending","contentLocale":"ja","term":"DeFiレンディング","aka":["DeFi貸付","レンディングプロトコル","DeFi lending","分散型レンディング"],"short":"DeFiレンディングとは、スマートコントラクト上で暗号資産を貸し出して利息を得たり、担保を預けて別の暗号資産を借りたりできる仕組みです。","body":[["AaveやCompoundなどが代表的です。貸し手は",["プール","liquidity-pool"],"に資産を預けて利息を受け取り、借り手は担保を預けてそこから借ります。金利はプールの利用率に応じて自動的に変わり、借りる人が多いほど上がります。"],"借入は過剰担保が基本です。担保価値に対して借りられる上限が決まっていて、担保の価格が下がって一定の水準を下回ると、清算人が担保の一部を割安に買い取る形で強制的に清算されます。",["担保の価格は",["オラクル","oracle"],"から取得されます。そのため、急な価格変動やオラクルの異常があると、短時間で清算が連鎖することがあります。借入をする場合は、余裕のある担保率を保ち、ヘルスファクターなどの指標を定期的に確認しましょう。"]],"example":"5 ETHを担保に預け、ETHが2,500ドルなら担保価値は12,500ドルです。清算しきい値が80%と仮定し、6,000 USDCを借りたとします。ヘルスファクターは12,500かける0.8を6,000で割った約1.67です。担保価値が7,500ドル、つまりETHが1,500ドルまで下がるとヘルスファクターが1になり、清算が始まります。借入を4,000 USDCに抑えれば、清算ラインはETH1,000ドルまで下がります。","mistakes":["借入上限ぎりぎりまで借りて、わずかな価格下落で清算されること。","借入金利が変動することを知らず、金利の上昇で返済額が増えること。","価格が急落しているときに担保の追加が間に合うと考え、余裕を持たないこと。"],"faq":[{"q":"DeFiで借りるときに審査はありますか？","a":"信用審査はなく、担保を預ければ誰でも借りられます。その代わり、担保価値が不足すると自動的に清算されます。"},{"q":"清算されるとどれくらい損をしますか？","a":"担保の一部が清算ペナルティ分だけ割安で売却されるため、その分が損失になります。ペナルティの水準はプロトコルや資産ごとに異なります。"}],"title":"DeFiレンディングとは？担保・金利・清算の仕組み","description":"DeFiレンディングの意味、過剰担保での借入や変動金利の仕組み、ヘルスファクターと清算ラインの計算例をわかりやすく解説します。","related":[["defi","DeFi（分散型金融）","DeFi（分散型金融）とは、銀行や取引所などの仲介者を通さず、ブロックチェーン上のスマートコントラクトで交換、貸し借り、利回り運用などを行う金融サービスの総称です。"],["liquidation","強制ロスカット（清算）","強制ロスカット（清算）とは、レバレッジ取引で損失が膨らみ、証拠金が維持証拠金を下回ったときに、取引所がポジションを強制的に決済する仕組みです。"],["oracle","オラクル（ブロックチェーンオラクル）","オラクルとは、価格や天気、試合結果など、ブロックチェーンの外にあるデータをスマートコントラクトに届ける仕組みのことです。"],["crypto-backed-stablecoin","暗号資産担保型ステーブルコイン","暗号資産担保型ステーブルコインとは、ETHなどの暗号資産をスマートコントラクトに預け入れ、その担保価値を上回らない範囲で発行されるステーブルコインのことです。"],["flash-loan","フラッシュローン","フラッシュローンとは、担保なしで暗号資産を借りられる代わりに、同じトランザクション内で必ず返済しなければならないDeFi特有の借入です。"]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"cbdc":{"slug":"cbdc","cat":"stablecoins","en":"CBDC (central bank digital currency)","contentLocale":"ja","term":"CBDC（中央銀行デジタル通貨）","aka":["中央銀行デジタル通貨","デジタル円","CBDC"],"short":"CBDCとは、中央銀行が発行し、現金や中央銀行預金と同じく中央銀行の直接の負債となるデジタル形式の法定通貨のことです。","body":[["CBDCは国の通貨そのものをデジタル化したもので、民間企業が発行する",["ステーブルコイン","stablecoin"],"や、発行体のいない",["ビットコイン","bitcoin"],"とは性質が異なります。価値は法定通貨と1対1で、中央銀行が発行・管理します。日本銀行も「デジタル円」について実証実験や制度設計の検討を進めています。"],"一般の人が使う「リテール型」と、金融機関同士の決済に使う「ホールセール型」があります。中国のデジタル人民元のように実証運用が広く進んでいる例もあれば、検討段階にとどまる国もあり、状況は国ごとに大きく異なります。",["CBDCは必ずしもパブリック",["ブロックチェーン","blockchain"],"上で動くわけではなく、多くは中央銀行が管理するシステムで運用される想定です。プライバシーの扱い、銀行預金への影響、オフライン決済の可否などが主な論点です。"]],"example":["ある国でCBDCが導入され、あなたが銀行口座から10,000円分をCBDC",["ウォレット","crypto-wallet"],"に移したとします。この10,000円は中央銀行の負債なので、銀行が経営難になっても価値は変わりません。一方、同じ10,000円で民間のステーブルコインを買った場合、その価値は発行体の準備資産に依存します。CBDCで3,000円を店で支払えば残高は7,000円となり、手数料や処理時間は制度設計次第です。投資商品ではないため、CBDC自体の価格が上下することはありません。"],"mistakes":["CBDCをビットコインのような値上がりを狙える暗号資産の一種だと考えてしまう。","「デジタル円」の名前を使った未発行トークンの販売話を本物だと信じてしまう。","CBDCとステーブルコインを同じものとして扱い、発行体と裏付けの違いを無視する。"],"faq":[{"q":"デジタル円はもう発行されていますか？","a":"日本銀行は実証実験や制度面の検討を進めていますが、発行するかどうかはまだ決まっていません。デジタル円を名乗るトークンの販売は詐欺の可能性が高いので注意が必要です。"},{"q":"CBDCとステーブルコインの違いは何ですか？","a":"CBDCは中央銀行が発行する法定通貨そのものです。ステーブルコインは民間企業が発行し、準備資産によって価値を支えています。"}],"title":"CBDCとは？中央銀行デジタル通貨の意味と仕組み","description":"CBDC（中央銀行デジタル通貨）の意味、ステーブルコインやビットコインとの違い、デジタル円の検討状況と注意点を解説します。","related":[["stablecoin","ステーブルコイン","ステーブルコインとは、米ドルなどの法定通貨や他の資産に価格が連動するよう設計された暗号資産で、価格変動を抑えて決済や取引の基軸に使われます。"],["fiat-on-ramp","法定通貨オンランプ（入金ルート）","法定通貨オンランプとは、円やドルなどの法定通貨を暗号資産に交換するための入口となるサービスや手段のことで、銀行振込、クレジットカード、P2P取引などがあります。"],["kyc","KYC（本人確認）","KYCとは、暗号資産取引所や金融機関が口座開設時などに、身分証明書や顔写真によって利用者の本人確認を行う手続きのことです。"],["blockchain","ブロックチェーン","ブロックチェーンとは、取引記録を「ブロック」にまとめて時系列に鎖のようにつなぎ、多数のコンピューターで共有・検証する分散型の台帳技術です。"]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDTは米ドルですか？なぜ暗号資産を買う時によく見かけるの？"},"coin":null,"tool":null,"cta":false},"node":{"slug":"node","cat":"onchain","en":"Node","contentLocale":"ja","term":"ノード（Node）","aka":["フルノード","node"],"short":"ノードとは、ブロックチェーンのネットワークに参加し、取引やブロックのデータを保存・検証・中継するコンピューターのことです。","body":[[["ブロックチェーン","blockchain"],"には中央のサーバーがなく、世界中のノードが同じ台帳のコピーを持ち合うことで成り立っています。新しい取引やブロックが届くと、各ノードはそれがルールに沿っているかを自分で検証し、正しいものだけを受け入れて他のノードに伝えます。"],["ノードにはいくつか種類があります。全履歴を保存して検証する「フルノード」、必要な情報だけを確認する「ライトノード」、ブロックを作る役割を持つマイナーや",["バリデーター","validator"],"のノードなどです。",["イーサリアム","ethereum"],"のような",["プルーフ・オブ・ステーク","proof-of-stake"],"では、",["ステーキング","staking"],"したバリデーターがノードを運用してブロックの提案や承認を行います。"],["自分でノードを運用すると、他人のサーバーを信頼せずに自分の取引を確認でき、プライバシーも高まります。",["ウォレット","crypto-wallet"],"アプリの多くは外部のノード（RPCプロバイダー）に接続しているので、その接続先が止まると残高表示や送金ができなくなることがあります。"]],"example":"ビットコインのフルノードを自宅で動かす場合を考えてみましょう。全履歴を保存するには数百GBのストレージが必要で、仮に600GBなら1TBのSSDを用意すれば当面は余裕があります。初回の同期には回線とパソコンの性能によって数日かかることがあります。ストレージを節約したいなら、古いブロックを削除する「プルーニング」設定で、たとえば10GB程度に抑えることもできます。この場合も取引の検証は自分で行えますが、過去のブロックを他のノードに提供することはできなくなります。","mistakes":["ノードを運用すればマイニングのように報酬がもらえると思い込む。","ストレージの容量や回線の通信量を確認せずに始め、途中で同期が止まってしまう。","ウォレットの接続先ノードを不明なRPCに変更するよう求めるサイトの指示に従ってしまう。"],"faq":[{"q":"ビットコインのノードを動かすと報酬はもらえますか？","a":"ビットコインのフルノードを運用するだけでは報酬はありません。報酬を得るのはブロックを作るマイナーで、ノード運用の利点は自分で取引を検証できることにあります。"},{"q":"ノードとバリデーターの違いは何ですか？","a":"ノードはネットワークに参加してデータを検証・中継するコンピューター全般です。バリデーターはプルーフ・オブ・ステークでステーキングを行い、ブロックの提案や承認を担う特別な役割のノードです。"}],"title":"ノードとは？ブロックチェーンでの役割と種類","description":"ブロックチェーンのノードの意味と役割、フルノードとライトノードやバリデーターの違い、自分で運用するときのポイントを解説します。","related":[["blockchain","ブロックチェーン","ブロックチェーンとは、取引記録を「ブロック」にまとめて時系列に鎖のようにつなぎ、多数のコンピューターで共有・検証する分散型の台帳技術です。"],["validator","バリデーター（検証者）","バリデーターとは、プルーフ・オブ・ステークのブロックチェーンで暗号資産をステークし、ブロックの提案や取引の検証を行うネットワーク参加者のことです。"],["mining","マイニング（採掘）","マイニング（採掘）とは、プルーフ・オブ・ワークのブロックチェーンで計算処理を行って取引をブロックにまとめ、その報酬として新規発行の暗号資産と手数料を受け取る活動です。"],["mempool","メンプール（Mempool）","メンプールとは、送信されたもののまだブロックに取り込まれていない未承認の取引が一時的に待機している場所のことです。"]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"aml":{"slug":"aml","cat":"regulation","en":"AML (anti-money laundering)","contentLocale":"ja","term":"AML（マネーロンダリング対策）","aka":["マネロン対策","AML/CFT","Anti-Money Laundering"],"short":"AMLとは、犯罪で得た資金の出どころを隠す行為（マネーロンダリング）を防ぐために、金融機関や暗号資産取引所が行う監視・確認・報告の仕組み全体のことです。","body":[["AMLには、口座開設時の",["本人確認","kyc"],"（KYC）だけでなく、取引のモニタリング、疑わしい取引の当局への届出、制裁対象者のチェック、送金時の情報共有（",["トラベルルール","travel-rule"],"）などが含まれます。テロ資金供与対策（CFT）とあわせて「AML/CFT」と呼ばれることもあります。"],[["暗号資産","cryptocurrency"],"取引所では、入金された資金がどの",["アドレス","wallet-address"],"から来たかを",["ブロックチェーン","blockchain"],"分析ツールで確認しています。詐欺やハッキング、ミキサー（資金の出どころを混ぜて隠すサービス）に関係するアドレスから届いた資金は、入金が保留されたり、追加の説明を求められたりすることがあります。"],"利用者にとって大切なのは、資金の出どころを説明できるようにしておくことです。給与や売却益など正当な資金でも、急に大きな額を動かすと確認が入ることがあり、その際は取引履歴や入金元の証明を求められる場合があります。"],"example":["あなたが",["P2P取引","p2p-trading"],"で知らない相手から2,000 USDTを受け取り、そのまま取引所に入金したとします。取引所の分析ツールが、その2,000 USDTの一部が過去に詐欺に関係したアドレスを経由していると判定すると、入金が凍結され、資金の入手経緯の説明を求められることがあります。このとき、P2P取引の注文番号、相手とのやり取り、銀行振込の記録を提出できれば、確認がスムーズに進みやすくなります。記録がないと、数週間以上かかったり、資金が返還されなかったりするケースもあります。"],"mistakes":["AMLの確認を受けたことに腹を立て、資金の出どころの説明を拒否して手続きを長引かせる。","出どころの不明な安いUSDTを受け取り、後で取引所の入金で凍結される。","取引所での確認を避けるために入金を小さく分割し、かえって不審な取引として扱われる。"],"faq":[{"q":"AMLで入金が凍結されたらどうすればよいですか？","a":"取引所の公式サポートに連絡し、資金の入手経緯を示す書類や取引履歴を提出します。SNSで「凍結を解除できる」と言ってくる第三者は詐欺の可能性が高いです。"},{"q":"AMLとKYCの違いは何ですか？","a":"KYCは利用者が誰かを確認する手続きで、AMLの一部です。AMLは取引の監視や報告まで含む、より広い仕組みを指します。"}],"title":"AMLとは？暗号資産のマネーロンダリング対策","description":"AML（マネーロンダリング対策）の意味、KYCとの違い、取引所で入金が凍結される理由と、利用者が準備しておくべきことを解説します。","related":[["kyc","KYC（本人確認）","KYCとは、暗号資産取引所や金融機関が口座開設時などに、身分証明書や顔写真によって利用者の本人確認を行う手続きのことです。"],["travel-rule","トラベルルール","トラベルルールとは、暗号資産を取引所間などで送るときに、送金人と受取人の氏名などの情報を事業者同士で共有することを求める国際的なルールです。"],["vasp","VASP（暗号資産サービス提供者）","VASPとは、暗号資産の交換、送金、保管などのサービスを業として提供する事業者を指すFATFの用語で、取引所やカストディ業者などが該当します。"],["p2p-trading","P2P取引（個人間取引）","P2P取引とは、取引所が仲介役となり、利用者同士が銀行振込などの法定通貨とUSDTなどの暗号資産を直接交換する取引方法です。"]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"KYC（本人確認）の仕組みと、身分証は誰に提出すべきか？"},"coin":null,"tool":null,"cta":false},"tokenized-gold":{"slug":"tokenized-gold","cat":"tokenized-assets","en":"Tokenized gold","contentLocale":"ja","term":"トークン化ゴールド（金トークン）","aka":["金トークン","ゴールドトークン","PAXG","XAUT"],"short":"トークン化ゴールドとは、発行体が保管する現物の金に裏付けられ、その金の一定量を表すトークンとしてブロックチェーン上で取引できる暗号資産のことです。","body":["代表例は、Paxosが発行するPAX Gold（PAXG）と、Tetherが発行するTether Gold（XAUT）で、どちらも1トークンが金1トロイオンスに相当するように設計されています。金は専門の保管庫に保管され、トークンを持つことでその金に対する権利を持つ仕組みです。",["金地金を自分で保管する手間がなく、0.01トークンのような小口でも保有でき、24時間いつでも送金や売買ができるのが特徴です。",["暗号資産","cryptocurrency"],"取引所で、USDTなどの",["ステーブルコイン","stablecoin"],"との",["取引ペア","trading-pair"],"で売買されることが多いです。"],"一方で、価値は発行体が本当に金を保有しているかどうかに依存します。保有状況の監査報告、現物の金への交換ができるかどうか、その最低数量や手数料を確認しましょう。取引所での価格は、需給によって金の現物価格からわずかに離れることもあります。"],"example":"金の価格が1トロイオンス2,500ドルのときに、あなたが500ドル分のPAXGを購入したとします。受け取るのは500÷2,500で0.2 PAXG、つまり金0.2トロイオンス分です。1トロイオンスは約31.1グラムなので、約6.2グラムの金を保有していることになります。金の価格が2,750ドルに10%上がれば、評価額は約550ドルです。ただし取引所の板が薄く、売るときの価格が金の現物価格より1%低ければ、受け取れるのは約544.5ドルになります。数字は説明用の例です。","mistakes":["トークン化ゴールドは発行体の信用に依存することを忘れ、金そのものと完全に同じだと考える。","取引所の価格が金の現物価格と常に一致していると考え、板の薄い時間帯に大きく売買する。","現物の金への交換条件や最低数量を確認せず、いつでも少量から金に交換できると思い込む。"],"faq":[{"q":"PAXGとXAUTの違いは何ですか？","a":"どちらも1トークンが金1トロイオンスに相当するよう設計されています。主な違いは発行体、保管場所、監査の方法、対応するブロックチェーンや交換条件です。"},{"q":"トークン化ゴールドは現物の金に交換できますか？","a":"発行体によっては、一定の数量以上で現物の金への交換や引き出しに対応しています。最低数量や手数料、対象地域は発行体ごとに確認が必要です。"}],"title":"トークン化ゴールドとは？PAXGなど金トークンの仕組み","description":"トークン化ゴールド（金トークン）の意味と仕組み、PAXGやXAUTの例、金現物との違いと発行体の信用など確認すべき点を解説します。","related":[["real-world-assets","RWA（現実資産のトークン化）","RWAとは、国債、株式、不動産、金、貸付債権など、ブロックチェーンの外にある現実の資産を、トークンとしてブロックチェーン上で表現したもの、またはその分野のことです。"],["stablecoin","ステーブルコイン","ステーブルコインとは、米ドルなどの法定通貨や他の資産に価格が連動するよう設計された暗号資産で、価格変動を抑えて決済や取引の基軸に使われます。"],["custodial-wallet","カストディアルウォレット（管理型ウォレット）","カストディアルウォレットとは、暗号資産の秘密鍵を取引所やサービス事業者が管理し、利用者はIDとパスワードなどでアカウントにログインして資産を使う形のウォレットです。"],["tokenized-stocks","トークン化株式","トークン化株式とは、実際の株式や株式に連動する権利をブロックチェーン上のトークンとして発行し、暗号資産と同じように保有や送金ができるようにしたものです。"]],"lesson":null,"coin":{"slug":"pax-gold","name":"PAX Gold","symbol":"PAXG"},"tool":"/topics/tokenized-assets","cta":false}});
